// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, STATS, TEXT_LINES } from './script'

const METRIC_TILES = [
  { d: 'words', label: 'Words', value: STATS.words },
  { d: 'chars', label: 'Characters', value: STATS.characters },
  { d: 'sentences', label: 'Sentences', value: STATS.sentences },
  { d: 'read', label: 'Reading time', value: STATS.readingTimeSeconds, suffix: ' s' },
]

const LINE_TILES = [
  { d: 'lines', label: 'Total lines', value: STATS.lines },
  { d: 'nonblank', label: 'Non-blank', value: STATS.nonBlank },
  { d: 'blank', label: 'Blank', value: STATS.blankLines },
]

const AVG_TILES = [
  { d: 'avgw', label: 'Avg word length', value: STATS.avgWordLength },
  { d: 'avgs', label: 'Avg sentence length', value: STATS.avgSentenceLength },
]

const build: Build = ({ tl, q, qa, step, final, move, click, count, wait, cursorOut }) => {
  step(0)
  move('editor', { at: 0.3, ax: 0.15, ay: 0.3 })
  click('editor')
  tl.fromTo(
    qa('word'),
    { opacity: 0 },
    { opacity: 1, duration: 0.05, stagger: 0.025, ease: 'none' },
  )
  cursorOut('<0.6')

  step(1, '+=0.3')
  move('metrics')
  click('metrics')
  tl.fromTo(q('metrics-panel'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.35 })
  tl.fromTo(
    qa('metric-tile'),
    { y: 10, opacity: 0.3 },
    { y: 0, opacity: 1, duration: 0.4, stagger: 0.08 },
  )
  METRIC_TILES.forEach((tile, index) =>
    count(tile.d, tile.value, {
      at: index === 0 ? '<' : '<0.08',
      duration: 0.9,
      suffix: tile.suffix,
      decimals: tile.d === 'read' ? 0 : tile.d === 'avgs' || tile.d === 'avgw' ? 1 : 0,
    }),
  )
  AVG_TILES.forEach((tile, index) =>
    count(tile.d, tile.value, {
      at: `<0.${index + 2}`,
      duration: 0.8,
      decimals: 1,
    }),
  )

  step(2, '+=0.6')
  move('lines')
  click('lines')
  tl.to(q('metrics-panel'), { opacity: 0, y: -6, duration: 0.25 })
  tl.fromTo(q('lines-panel'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.35 }, '<0.1')
  LINE_TILES.forEach((tile, index) =>
    count(tile.d, tile.value, {
      at: index === 0 ? '<0.15' : '<0.1',
      duration: 0.8,
    }),
  )

  step(3, '+=0.5')
  move('copy')
  click('copy')
  tl.fromTo(q('copied'), { opacity: 0, scale: 0.9 }, { opacity: 1, scale: 1, duration: 0.3 })
  final('+=0.4')
  wait(1.2)
}

export default function Demo() {
  return (
    <DemoStage
      label="Text Analyzer counting words and characters, showing metrics and line counts"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <p
            data-d="editor"
            className="h-[86px] overflow-hidden rounded-xl border border-line bg-canvas/80 px-3 py-2 text-[11px] leading-[17px] text-ink-soft"
          >
            {TEXT_LINES.map((line, row) => (
              <span key={row} className="block truncate">
                {line.split(' ').map((word, index) => (
                  <span key={index} data-d="word">
                    {word}{' '}
                  </span>
                ))}
              </span>
            ))}
          </p>
          <div className="flex gap-1.5">
            <Btn d="metrics" primary>
              Metrics
            </Btn>
            <Btn d="lines">Lines</Btn>
          </div>
          <div className="relative min-h-0 flex-1">
            <div data-d="metrics-panel" className="space-y-2">
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                {METRIC_TILES.map((tile) => (
                  <div
                    key={tile.d}
                    data-d="metric-tile"
                    className="rounded-xl border border-line bg-canvas/60 px-2.5 py-2"
                  >
                    <p className="text-[9px] text-muted">{tile.label}</p>
                    <p className="mt-0.5 text-[18px] font-semibold leading-none tracking-tight">
                      <span data-d={tile.d}>0</span>
                      {tile.suffix ?? ''}
                    </p>
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {AVG_TILES.map((tile) => (
                  <div
                    key={tile.d}
                    className="rounded-xl border border-line bg-canvas/60 px-2.5 py-2"
                  >
                    <p className="text-[9px] text-muted">{tile.label}</p>
                    <p className="mt-0.5 text-[16px] font-semibold leading-none">
                      <span data-d={tile.d}>0</span>
                    </p>
                  </div>
                ))}
              </div>
            </div>
            <div data-d="lines-panel" className="absolute inset-0 opacity-0">
              <Label>Lines</Label>
              <div className="mt-2 grid grid-cols-3 gap-2">
                {LINE_TILES.map((tile) => (
                  <div
                    key={tile.d}
                    className="rounded-xl border border-line bg-canvas/60 px-2.5 py-2"
                  >
                    <p className="text-[9px] text-muted">{tile.label}</p>
                    <p className="mt-0.5 text-[18px] font-semibold leading-none">
                      <span data-d={tile.d}>0</span>
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </div>
          <div className="flex justify-end gap-2">
            <Btn d="copy">Copy</Btn>
            <Btn d="clear">Clear</Btn>
          </div>
          <p
            data-d="copied"
            className="pointer-events-none absolute bottom-3 right-3 rounded-full bg-emerald/15 px-2.5 py-1 font-mono text-[10px] text-emerald opacity-0"
          >
            Copied
          </p>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
